import re, glob, os
from datetime import date, timedelta

ref = date(2025, 8, 12)
all_counts = {}

for path in sorted(glob.glob("/app/logs/*.log")):
    base = os.path.basename(path)
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", base)
    d = date.fromisoformat(m.group(1))
    counts = {"ERROR":0, "WARNING":0, "INFO":0, "DEBUG":0, "TRACE":0, "FATAL":0, "CRITICAL":0}
    with open(path) as f:
        for line in f:
            sm = re.search(r"\[([A-Z]+)\]", line)
            if sm and sm.group(1) in counts:
                counts[sm.group(1)] += 1
    if d not in all_counts:
        all_counts[d] = {"ERROR":0, "WARNING":0, "INFO":0, "DEBUG":0, "TRACE":0, "FATAL":0, "CRITICAL":0}
    for k, v in counts.items():
        all_counts[d][k] += v

today = ref
last7 = {ref - timedelta(days=k) for k in range(0, 7)}
last30 = {ref - timedelta(days=k) for k in range(0, 30)}
month_to_date = set()
d = date(2025, 8, 1)
while d <= ref:
    month_to_date.add(d)
    d += timedelta(days=1)

total = set(all_counts.keys())

periods = [
    ("today", {ref}),
    ("last_7_days", last7),
    ("last_30_days", last30),
    ("month_to_date", month_to_date),
    ("total", total),
]

lines = ["period,severity,count"]
for period, dates in periods:
    for sev in ["ERROR", "WARNING", "INFO"]:
        c = 0
        if period == "total":
            for d, cnt in all_counts.items():
                c += cnt.get(sev, 0)
        else:
            for d in dates:
                c += all_counts.get(d, {}).get(sev, 0)
        lines.append(f"{period},{sev},{c}")

with open("/app/summary.csv", "w") as f:
    f.write("\n".join(lines) + "\n")
EOF

